    "adm3_546405c33b": "З аукціону",
    "adm3_86a6e3e43d": "Неактивний",
    "adm3_6c4bee09e1": "Активний",
    "adm3_b874d83ea3": "Динамічна конфігурація автентифікації — base URL, Google OAuth, JWT,\n          feature flags і password policy. Все читається з БД (колекція",
    "adm3_c525139017": "),\n          тому для переносу на новий домен достатньо змінити одне поле без деплою.",
    "adm3_77e3eecbd2": "Resend (згодом)",
    "adm3_4733065469": "SMTP (згодом)",
    "adm3_a6c4d0e909": "Статуси — частина бізнес-логіки системи. Зміна потребує міграції\n        існуючих даних — зверніться до розробки.",
    "adm3_9f3b3510e5": "Введіть поточний код із Google Authenticator для відключення:",
    "adm3_1c25c4c013": "Двофакторна автентифікація (Google Authenticator)",
    "adm3_80a84dca0b": "Невірний код",
    "adm3_d15a1ace8d": "Підтвердити",
    "adm3_dee9a2d8d9": "Немає даних",
    "adm3_1153a09c67": "Name (наприклад MSC OSCAR)",
    "adm3_f4866953d8": "Помилка активації",
    "adm3_250b47cecd": "Немає відправлень",
    "adm3_e40073a22b": "Помилка переходу",
    "adm3_ba681ad00b": "Морський",
    "adm3_91843347db": "Наземний",
    "adm3_8964d94a1b": "Порт",
    "adm3_cc8fbb20a2": "на активному морському етапі.\n                  Resolver шукає джерело в: shipment fields → events → deal → related shipments → text regex → ShipsGo.",
    "adm3_3d7afec746": "Ідентифікатор відправлення (якщо знаєш напряму)",
    "adm3_638c49bee6": "— реальні листи не надсилаються. Додайте RESEND_API_KEY у backend/.env для production.",
    "adm3_7cc60ff3e9": "Об'єднаний хаб для всіх системних налаштувань — авторизація,\n            публічні URL, email і CRM-конфіг в одному місці.",
    "adm3_36e220d142": "Ціни на автомобілі після аварії зі США…",
    "adm3_29f3b5a5cf": "Напишіть статтю українською…",
    "adm3_a5aeb1abd6": "Кожне розширення-менеджера підписує запити власним секретом. Секрет видається\n        лише один раз при створенні або ротації.",
    "adm3_caa452faa9": "Пропущено (вже мали активний):",
    "adm3_b1211eb53f": "Згенерувати новий secret? Старий одразу перестане працювати.",
    "adm3_e6eda2f1ae": "🚀 Bootstrap усіх менеджерів",
    "adm3_82752e3944": "Введіть дату передзвону (напр. 2026-04-01 14:00):",
    "adm3_34df85665b": "Наступна дія:",
    "adm3_19c2985089": "Прострочено:",
    "adm3_567938d94c": "; сповіщення надішлються клієнту\n                      та менеджеру. Всі дії ідемпотентні — повторний клік\n                      не створить дублікатів.",
    "adm3_eb8fcce11b": "Це попередній розрахунок. Після підтвердження breakdown буде\n            записаний у БД з",
    "adm3_9035ff8358": "after-win breakdown буде створено автоматично. Фінал — кнопкою вище.",
    "adm3_18ed2322c4": "клієнт повинен мати всі 7 юридичних\n              полів (таб",
    "adm3_d9c11612de": "Override default fees (опціонально)",
    "adm3_cc81b80a34": "Оплачено зараз, EUR (може бути 0)",
    "adm3_619f0e009f": "Усі 20 стадій (детально)",
