    "adm3_6c4bee09e1": "Active",
    "adm3_b874d83ea3": "Dynamic authentication configuration — base URL, Google OAuth, JWT,\n          feature flags and password policy. All read from DB (collection",
    "adm3_c525139017": "),\n          so to transfer to a new domain, it is enough to change one field without deployment.",
    "adm3_77e3eecbd2": "Resend (soon)",
    "adm3_4733065469": "SMTP (soon)",
    "adm3_a6c4d0e909": "Statuses are part of the system's business logic. Changes require data migration – please contact development.",
    "adm3_9f3b3510e5": "Enter current Google Authenticator code to disable:",
    "adm3_1c25c4c013": "Two-factor authentication (Google Authenticator)",
    "adm3_80a84dca0b": "Invalid code",
    "adm3_d15a1ace8d": "Confirm",
    "adm3_dee9a2d8d9": "No data",
