    "adm3_ba681ad00b": "Sea",
    "adm3_91843347db": "Ground",
    "adm3_8964d94a1b": "Port",
    "adm3_cc8fbb20a2": "in the active sea stage.\n                  Resolver looks for source in: shipment fields → events → deal → related shipments → text regex → ShipsGo.",
    "adm3_3d7afec746": "Shipment ID (if known directly)",
    "adm3_638c49bee6": "— real emails are not sent. Add RESEND_API_KEY to backend/.env for production.",
    "adm3_7cc60ff3e9": "Unified hub for all system settings — authentication,\n            public URLs, email, and CRM config in one place.",
    "adm3_36e220d142": "Prices for post-accident cars from USA…",
    "adm3_29f3b5a5cf": "Write the article in Bulgarian...",
    "adm3_a5aeb1abd6": "Each manager extension signs requests with its own secret. The secret is issued\n        only once upon creation or rotation.",
    "adm3_caa452faa9": "Skipped (already had an active one):",
    "adm3_b1211eb53f": "Generate new secret? The old one will immediately stop working.",
    "adm3_e6eda2f1ae": "🚀 Bootstrap all managers",
    "adm3_82752e3944": "Enter callback date (e.g., 2026-04-01 14:00):",
    "adm3_34df85665b": "Next action:",
    "adm3_19c2985089": "Overdue:",
    "adm3_567938d94c": "; notifications will be sent to the client\n                      and manager. All actions are idempotent — repeated clicks\n                      will not create duplicates.",
    "adm3_eb8fcce11b": "This is a preliminary calculation. After confirmation, the breakdown will be\n            recorded in the DB with",
    "adm3_9035ff8358": "after-win breakdown will be created automatically. Final — with the button above.",
    "adm3_18ed2322c4": "client must have all 7 legal\n              fields (tab",
    "adm3_d9c11612de": "Override default fees (optional)",
